// Generated from assets/brand/source.svg; retain source geometry when refreshing assets.
const assets = new Map([["/favicon.svg","image/svg+xml; charset=utf-8",""],["/favicon.ico","image/x-icon",""],["/favicon-96x96.png","image/png",""],["/apple-touch-icon.png","image/png",""],["/web-app-manifest-192x192.png","image/png",""],["/web-app-manifest-512x512.png","image/png",""],["/site.webmanifest","application/manifest+json; charset=utf-8",""]].map(([path, type, base64]) => [path, { type, base64 }]));

export const faviconHead = "<link rel=\"icon\" type=\"image/svg+xml\" href=\"/favicon.svg?v=branding-v1\" />\n<link rel=\"icon\" type=\"image/png\" sizes=\"96x96\" href=\"/favicon-96x96.png?v=branding-v1\" />\n<link rel=\"shortcut icon\" href=\"/favicon.ico?v=branding-v1\" />\n<link rel=\"apple-touch-icon\" sizes=\"180x180\" href=\"/apple-touch-icon.png?v=branding-v1\" />\n<meta name=\"apple-mobile-web-app-title\" content=\"Userorbit\" />\n<meta name=\"theme-color\" content=\"#4f46e5\" />\n<link rel=\"manifest\" href=\"/site.webmanifest?v=branding-v1\" />";

export function brandAssetResponse(path) {
  const asset = assets.get(path.split("?")[0]);
  if (!asset) return null;
  asset.bytes ||= Uint8Array.from(atob(asset.base64), (character) => character.charCodeAt(0));
  return new Response(asset.bytes, {
    headers: {
      "content-type": asset.type,
      "cache-control": "public, max-age=86400, stale-while-revalidate=604800",
      "x-content-type-options": "nosniff",
    },
  });
}
